function calendlyMauticFields({ invitee }) {
  if (!invitee || typeof invitee !== 'object' || Array.isArray(invitee) || typeof invitee.email !== 'string' || !invitee.email.trim() || typeof invitee.name !== 'string' || !invitee.name.trim()) {
    throw new Error('The Calendly booking must contain an invitee email and name');
  }
  return { fields: { email: invitee.email, firstname: invitee.name, lastname: '', company: '', position: '', title: '' } };
}

return $input.all().flatMap((item, index) => item.json.event === "invitee.created" ? [{ json: calendlyMauticFields({ invitee: item.json.payload }).fields, pairedItem: { item: index } }] : []);

function mauticContactSaved({ contact }) {
  if (!contact || typeof contact !== 'object' || Array.isArray(contact) || !Number.isInteger(contact.id) || contact.id <= 0) {
    throw new Error('Mautic did not return a saved contact ID');
  }
  return { contact };
}

return { json: mauticContactSaved({ contact: $json }).contact };
